import{_ as e,o as r,c as d,a2 as o}from"./chunks/framework.CTx8wfac.js";const h=JSON.parse('{"title":"Error types","description":"","frontmatter":{},"headers":[],"relativePath":"reference/error-types.md","filePath":"reference/error-types.md"}'),a={name:"reference/error-types.md"};function s(n,t,c,i,l,p){return r(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="error-types" tabindex="-1">Error types <a class="header-anchor" href="#error-types" aria-label="Permalink to &quot;Error types&quot;">​</a></h1><p>All framework errors extend <strong><code>ApiError</code></strong> and carry an <strong><code>ErrorType</code></strong> enum value. Use <strong><code>ApiError.handle(err, res)</code></strong> inside custom middleware, or rely on <strong><code>ErrorMiddleware</code></strong> / <strong><code>createErrorMiddleware</code></strong> from the framework.</p><div class="tip custom-block"><p class="custom-block-title">Spelling</p><p>The class for HTTP <strong>401</strong> is <strong><code>UnauthorisedError</code></strong> (UK spelling), consistent with the <code>ErrorType.UNAUTHORISED</code> constant.</p></div><h2 id="classes-and-typical-http-status" tabindex="-1">Classes and typical HTTP status <a class="header-anchor" href="#classes-and-typical-http-status" aria-label="Permalink to &quot;Classes and typical HTTP status&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Class</th><th>Status</th><th>Use case</th></tr></thead><tbody><tr><td><code>BadRequestError</code></td><td>400</td><td>Invalid input / business rule</td></tr><tr><td><code>UnauthorisedError</code></td><td>401</td><td>Missing or bad credentials</td></tr><tr><td><code>PaymentRequiredError</code></td><td>402</td><td>Payment required</td></tr><tr><td><code>ForbiddenError</code></td><td>403</td><td>Authenticated but not allowed</td></tr><tr><td><code>NotFoundError</code></td><td>404</td><td>Resource missing</td></tr><tr><td><code>ConflictError</code></td><td>409</td><td>Version / uniqueness conflict</td></tr><tr><td><code>TooManyRequestsError</code></td><td>429</td><td>Rate limit / quota</td></tr><tr><td><code>InternalError</code></td><td>500</td><td>Unexpected failure</td></tr><tr><td><code>BadGatewayError</code></td><td>502</td><td>Upstream failure</td></tr><tr><td><code>ServiceUnavailableError</code></td><td>503</td><td>Maintenance / overload</td></tr><tr><td><code>GatewayTimeoutError</code></td><td>504</td><td>Upstream timeout</td></tr></tbody></table><h2 id="production-behavior" tabindex="-1">Production behavior <a class="header-anchor" href="#production-behavior" aria-label="Permalink to &quot;Production behavior&quot;">​</a></h2><p>For <strong><code>InternalError</code></strong>, user-facing messages may be replaced in <strong>production</strong> to avoid leaking internals (<code>NODE_ENV === &#39;production&#39;</code> path in <code>ApiError.handle</code>).</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/banana-universe/api/classes/ApiError.html">TypeDoc: <code>ApiError</code></a></li><li><a href="/banana-universe/guide/basic-concepts.html">Basic concepts</a></li></ul>',9)])])}const m=e(a,[["render",s]]);export{h as __pageData,m as default};
